# localpg-setup.ps1 - initialize + start the local PostgreSQL 17 (binaries ZIP,
# no install, no service, runs as the current user) with SSL on our local CA.
#
# Prereqs: binaries extracted to C:\Users\hs333\pgsql-local\pgsql (initdb.exe in
#          ...\pgsql\bin), certs generated by localpg-certs.cjs.
$ErrorActionPreference = "Stop"
$ROOT  = "C:\Users\hs333\pgsql-local"
$BIN   = "$ROOT\pgsql\bin"
$DATA  = "$ROOT\data"
$CERTS = "$ROOT\certs"

if (-not (Test-Path "$BIN\initdb.exe")) { throw "initdb.exe not found at $BIN" }
if (Test-Path "$DATA\PG_VERSION") { Write-Host "data dir already initialized - skipping initdb" }
else {
  & "$BIN\initdb.exe" -D $DATA -U postgres -A trust -E UTF8 --no-locale
  if ($LASTEXITCODE -ne 0) { throw "initdb failed" }
}

# port + SSL
$conf = Get-Content "$DATA\postgresql.conf" -Raw
if ($conf -notmatch "vk_local_done") {
  Add-Content "$DATA\postgresql.conf" @"

# --- vk_local_done ---
listen_addresses = '127.0.0.1'
port = 5433
ssl = on
ssl_cert_file = 'C:/Users/hs333/pgsql-local/certs/server.crt'
ssl_key_file  = 'C:/Users/hs333/pgsql-local/certs/server.key'
"@
}

& "$BIN\pg_ctl.exe" -D $DATA -l "$ROOT\pg.log" start
if ($LASTEXITCODE -ne 0) { throw "pg_ctl start failed (see $ROOT\pg.log)" }

# database
& "$BIN\psql.exe" -h 127.0.0.1 -p 5433 -U postgres -c "CREATE DATABASE railway"
Write-Host "local PostgreSQL up: postgres://postgres@127.0.0.1:5433/railway (db railway)"
